const csv = `date,campaign,spend_usd,clicks,purchases,revenue_usd
2026-11-07,Cat Tree - Broad,42.10,310,3,186.00
2026-11-07,Retargeting 30d,18.50,95,4,212.00
2026-11-08,Cat Tree - Broad,45.30,298,2,124.00
2026-11-08,Retargeting 30d,17.90,88,3,159.00
2026-11-09,Cat Tree - Broad,40.00,322,4,248.00
2026-11-09,Retargeting 30d,19.20,101,5,265.00
2026-11-10,Cat Tree - Broad,44.80,305,1,62.00
2026-11-10,Retargeting 30d,18.00,90,4,212.00
2026-11-11,Cat Tree - Broad,43.50,315,3,186.00
