2026-11-13,Cat Tree - Broad,41.90,308,3,186.00
2026-11-13,Retargeting 30d,18.30,93,4,212.00`;
// Sample Meta Ads rows for 7 days. Replace this node with an HTTP Request to the Meta Insights API later.
const [header, ...lines] = csv.trim().split('\n');
const keys = header.split(',');
return lines.map(line => {
  const v = line.split(',');
  const row = Object.fromEntries(keys.map((k, i) => [k, v[i]]));
  for (const k of ['spend_usd', 'clicks', 'purchases', 'revenue_usd']) row[k] = Number(row[k]);
  return { json: row };
});

// KPIs per campaign: latest day vs average of previous days
const rows = $input.all().map(i => i.json);
const dates = [...new Set(rows.map(r => r.date))].sort();
const latest = dates.at(-1);
const prevDates = new Set(dates.slice(0, -1));
const sum = (arr, k) => arr.reduce((s, r) => s + r[k], 0);
const r2 = n => n === null ? null : Math.round(n * 100) / 100;
const campaigns = [...new Set(rows.map(r => r.campaign))];
return campaigns.map(c => {
  const day = rows.filter(r => r.campaign === c && r.date === latest);
  const hist = rows.filter(r => r.campaign === c && prevDates.has(r.date));
  const spend = sum(day, 'spend_usd'), revenue = sum(day, 'revenue_usd'), purchases = sum(day, 'purchases');
  const hSpend = sum(hist, 'spend_usd'), hRev = sum(hist, 'revenue_usd'), hPurch = sum(hist, 'purchases');
  const roas = spend ? revenue / spend : 0;
  const roasAvg = hSpend ? hRev / hSpend : 0;
  return { json: {
    date: latest, campaign: c,
    spend: r2(spend), revenue: r2(revenue), purchases,
    roas: r2(roas), roas_avg_prev: r2(roasAvg),
    roas_change_pct: roasAvg ? r2((roas - roasAvg) / roasAvg * 100) : null,
    cpa: purchases ? r2(spend / purchases) : null,
    cpa_avg_prev: hPurch ? r2(hSpend / hPurch) : null,
    prev_days: prevDates.size,
  } };
});

// Build the report text + one rule-based recommendation (swap for a Claude node once the API is set up)
const k = $input.all().map(i => i.json);
const date = k[0].date;
const spend = k.reduce((s, x) => s + x.spend, 0);
const revenue = k.reduce((s, x) => s + x.revenue, 0);
const orders = k.reduce((s, x) => s + x.purchases, 0);
const roas = spend ? revenue / spend : 0;
const fmt = n => (n === null || n === undefined) ? '-' : n.toFixed(2);
const arrow = p => p === null ? '' : (p >= 0 ? ` (+${p.toFixed(0)}% vs ${k[0].prev_days}-day avg)` : ` (${p.toFixed(0)}% vs ${k[0].prev_days}-day avg)`);

const lines = k
  .sort((a, b) => b.roas - a.roas)
  .map(x => `- ${x.campaign}: spend $${fmt(x.spend)}, ROAS ${fmt(x.roas)}${arrow(x.roas_change_pct)}, CPA $${fmt(x.cpa)}`);

const worst = k.at(-1);
const rising = k.filter(x => x.roas_change_pct !== null).sort((a, b) => b.roas_change_pct - a.roas_change_pct)[0];
let rec;
if (worst.roas < 2) rec = `Cut "${worst.campaign}" budget by 20% and test a new creative (ROAS ${fmt(worst.roas)} is under 2.0).`;
else if (rising && rising.roas_change_pct >= 10) rec = `Scale "${rising.campaign}" by 15-20%: ROAS is up ${rising.roas_change_pct.toFixed(0)}% vs the recent average.`;
else rec = `Hold budgets: all campaigns are above ROAS 2.0 with no strong upward trend.`;

const report_text = [
  `Daily Ads Report - ${date}`,
  `Spend $${fmt(spend)} | Revenue $${fmt(revenue)} | Orders ${orders} | ROAS ${fmt(roas)}`,
  ``,
  `By campaign:`,
  ...lines,
  ``,
  `Recommendation: ${rec}`,
].join('\n');

return [{ json: { date, total_spend: +fmt(spend), total_revenue: +fmt(revenue), orders, roas: +fmt(roas), recommendation: rec, report_text } }];
